import{_ as d,o as t,c as o,ag as a}from"./chunks/framework.BFM5MFIQ.js";const m=JSON.parse('{"title":"Форматирование Markdown","description":"Внутренние ссылки, упоминания, теги и форматирование Markdown в Owlbear’s DMH.","frontmatter":{"title":"Форматирование Markdown","description":"Внутренние ссылки, упоминания, теги и форматирование Markdown в Owlbear’s DMH.","order":20},"headers":[],"relativePath":"ru/reference/markdown.md","filePath":"ru/reference/markdown.md"}'),r={name:"ru/reference/markdown.md"};function c(n,e,l,i,h,s){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="форматирование-markdown" tabindex="-1">Форматирование Markdown <a class="header-anchor" href="#форматирование-markdown" aria-label="Permalink to &quot;Форматирование Markdown&quot;">​</a></h1><h2 id="внутренние-ссылки" tabindex="-1">Внутренние ссылки <a class="header-anchor" href="#внутренние-ссылки" aria-label="Permalink to &quot;Внутренние ссылки&quot;">​</a></h2><p>Ссылайтесь на другие сущности кампании через <code>[название](тип://id)</code>:</p><ul><li><code>[Название заметки](note://123)</code> — ссылка на заметку</li><li><code>[Название модуля](module://123)</code> — ссылка на модуль</li><li><code>[Название группы](party://123)</code> — ссылка на группу</li><li><code>[Название монстра](pawn://123)</code> — ссылка на монстра</li><li><code>[Название схватки](encounter://123)</code> — ссылка на схватку</li></ul><h2 id="упоминания-сущностеи" tabindex="-1">Упоминания сущностей <a class="header-anchor" href="#упоминания-сущностеи" aria-label="Permalink to &quot;Упоминания сущностей&quot;">​</a></h2><p>Используйте кнопки упоминаний на панели редактора, чтобы связать заметку, модуль, группу, монстра или схватку. Упоминания используют тот же синтаксис внутренних ссылок:</p><p><code>[Таверна](note://123)</code> упоминает заметку «Таверна».</p><h2 id="теги" tabindex="-1">Теги <a class="header-anchor" href="#теги" aria-label="Permalink to &quot;Теги&quot;">​</a></h2><p>Введите <code>#</code> в редакторе, чтобы найти или создать тег, либо напишите хештег вручную. Теги собираются в меню параметров заметки.</p><ul><li><code>#tavern</code> добавляет тег «tavern».</li><li><code># Заголовок</code> заголовки вроде этого не считаются тегами.</li></ul><h2 id="markdown" tabindex="-1">Markdown <a class="header-anchor" href="#markdown" aria-label="Permalink to &quot;Markdown&quot;">​</a></h2><p>Базовое форматирование Markdown:</p><table tabindex="0"><thead><tr><th>Синтаксис</th><th>Результат</th></tr></thead><tbody><tr><td><code>**жирный**</code></td><td><strong>Жирный текст</strong></td></tr><tr><td><code>*курсив*</code></td><td><em>Курсив</em></td></tr><tr><td><code># Заголовок</code></td><td>Заголовок раздела</td></tr><tr><td><code>- пункт</code></td><td>Маркированный список</td></tr><tr><td><code>1. пункт</code></td><td>Нумерованный список</td></tr><tr><td><code>- [ ] Задача</code> / <code>- [x] Готово</code></td><td>Список задач с чекбоксами</td></tr></tbody></table><p>Списки задач, записанные как <code>- [ ]</code> или <code>- [x]</code>, отображаются как неактивные чекбоксы.</p>',14)])])}const k=d(r,[["render",c]]);export{m as __pageData,k as default};
